namespace DesktopCritters.Core;
public readonly record struct V(double X,double Y) {
 public static readonly V Zero=new(0,0);
 public static V operator +(V a,V b)=>new(a.X+b.X,a.Y+b.Y);
 public static V operator -(V a,V b)=>new(a.X-b.X,a.Y-b.Y);
 public static V operator *(V a,double k)=>new(a.X*k,a.Y*k);
 public static V operator /(V a,double k)=>a*(1/k);
 public double Length=>Math.Sqrt(X*X+Y*Y);public V Unit=>Length>.001?this*(1/Length):Zero;
 public double Distance(V b)=>(this-b).Length;
}
public enum Species { Roach,Ant }
public enum Snack { Cookie,Cake,Cheese,Strawberry,Pizza,Banquet }
public enum Tool { Food,Grab,Slipper,Broom,Observe,RoachEgg,AntEgg,Shelter=8,Spray=9 }
public enum Relation { Hostile,Truce,Trade }
public enum InvaderKind { Spider,Beetle,Centipede,Snake,Rat }
public enum Attack { Bite,Pincer,Ram,Swarm,Web }
public sealed class Bug {
 public int Id {get;set;} public Species Species {get;set;} public V P {get;set;} public double Angle {get;set;} public double Phase {get;set;}
 public double Growth {get;set;}=1;public double Bulk {get;set;} public double ShownBulk {get;set;} public int Meals {get;set;} public int Generation {get;set;}=1;
 public bool Breeder {get;set;} public int Cargo {get;set;} public double Health {get;set;}=10;public double Cooldown {get;set;}
 public V Wander {get;set;} public double WanderTime {get;set;} public double Hit {get;set;} public double Web {get;set;} public double BitePulse {get;set;} public double AttackCooldown {get;set;}
 [System.Text.Json.Serialization.JsonIgnore] public bool Walking {get;set;}
 [System.Text.Json.Serialization.JsonIgnore] public double AttackPose {get;set;}
 [System.Text.Json.Serialization.JsonIgnore] public RoachFlight? Flight {get;set;}
 [System.Text.Json.Serialization.JsonIgnore] public double? FlightWait {get;set;}
 public double LayTime {get;set;}
 public int? Opponent {get;set;} public bool Adult=>Growth>=1;public bool Soldier=>!Breeder&&Id%7==0;
 public double Toughness=>(Species==Species.Roach?10:4)*(Soldier?1.5:1)*(1+Bulk*6);
 public int Morph=>Growth<.3?0:Growth<1?1:Bulk<=.3?2:Bulk<.78?3:4;
 public string MorphTitle=>(Species==Species.Roach?new[]{"初生若虫","棕背若虫","成蟑","厚背成蟑","巨型蟑螂"}:new[]{"初生幼蚁","小工蚁","成蚁","巨颚兵蚁","巨型蚂蚁"})[Morph];
 public Bug Copy()=>(Bug)MemberwiseClone();
}
public sealed class Egg {public int Id {get;set;} public Species Species {get;set;} public V P {get;set;} public double Age {get;set;} public double HatchTime {get;set;} public int Brood {get;set;}=1;public V? LayStart {get;set;} public double? LayAge {get;set;} public int? ParentId {get;set;} [System.Text.Json.Serialization.JsonIgnore] public double Emission=>Math.Clamp((LayAge??3)/2.8,0,1); [System.Text.Json.Serialization.JsonIgnore] public V ShownPoint=>LayStart.HasValue?LayStart.Value+(P-LayStart.Value)*(Emission*Emission*(3-2*Emission)):P;public int Generation {get;set;}=2;}
public sealed class Food {public int Id {get;set;} public V P {get;set;} public Snack Snack {get;set;} public int Portions {get;set;} public int Original {get;set;} public double Angle {get;set;}}
public sealed class Invader {public int Id {get;set;} public InvaderKind Kind {get;set;} public V P {get;set;} public double Angle {get;set;} public double Phase {get;set;} public double Health {get;set;} public double Cooldown {get;set;}=1;public double Age {get;set;} public int Stolen {get;set;} public bool Dead=>Health<=0;}
public sealed class Drop {public V Offset {get;set;} public double Radius {get;set;} public double Flight {get;set;}}
public sealed class Splat {public int BugId {get;set;} public V P {get;set;} public double Radius {get;set;} public double Angle {get;set;} public bool Crushed {get;set;} public double Age {get;set;} public List<Drop> Drops {get;set;}=new();
 public bool Hit(V p,double padding) {var d=p-P;var local=new V(d.X*Math.Cos(Angle)+d.Y*Math.Sin(Angle),-d.X*Math.Sin(Angle)+d.Y*Math.Cos(Angle));return Math.Pow(local.X/(Radius*1.9+padding),2)+Math.Pow(local.Y/(Radius*.85+padding),2)<=1||Drops.Any(x=>local.Distance(x.Offset)<x.Radius+padding);}}
public sealed class Fight {public int Attacker=-1;public V From;public V To;public Attack Style;public double Size=1;public double Age;}
public sealed class Sweep {public V P;public double Age;public List<Bug> Bodies=new();public List<Splat> Stains=new();public List<Egg> Eggs=new();public List<Invader> Outsiders=new();}
public sealed class DayReport {public string Day {get;set;}="";public int RoachBorn {get;set;} public int AntBorn {get;set;} public int Grown {get;set;} public int RoachLost {get;set;} public int AntLost {get;set;} public int Swatted {get;set;} public int Delivered {get;set;} public int Trades {get;set;} public List<string> Events {get;set;}=new();}
public sealed class Snapshot {
 public int Version {get;set;}=1;public double Width {get;set;} public double Height {get;set;} public List<Bug> Bugs {get;set;}=new();public List<Bug> Corpses {get;set;}=new();public List<Egg> Eggs {get;set;}=new();public List<Food> Foods {get;set;}=new();public List<Splat> Splats {get;set;}=new();public List<Invader> Invaders {get;set;}=new();public List<DayReport> Reports {get;set;}=new();
 public System.Collections.Generic.List<EggShelter> Shelters {get;set;}=new();
 public int Serial {get;set;} public int FoodSerial {get;set;} public int RoachFood {get;set;} public int AntFood {get;set;} public int Deaths {get;set;} public int Hatched {get;set;} public int Grown {get;set;} public double RoachBirth {get;set;} public double AntBirth {get;set;} public double Clock {get;set;} public Relation Relation {get;set;} public double RelationAge {get;set;} public int DeathsAtPeace {get;set;} public int Archived {get;set;}
}
public sealed partial class World {
 public double Width,Height,Clock;public List<Bug> Bugs=new(),Corpses=new();public List<Egg> Eggs=new();public List<Food> Foods=new();public List<Splat> Splats=new();public List<Invader> Invaders=new();public List<DayReport> Reports=new();public List<Fight> Fights=new();public List<Sweep> Sweeps=new();
 public int Serial,FoodSerial,RoachFood=120,AntFood=180,Hatched,Grown,Deaths,Archived;public double RoachBirth=6,AntBirth=5;
 public bool Paused,Interactive,Battle,Result,Sound;public double Remaining=150,LifeRate=1;public int RoachScore,AntScore;public Tool Tool;public Snack SelectedSnack;
 public Relation Relation=Relation.Hostile;public double RelationAge;public int DeathsAtPeace;public double TradeTimer,AutoFoodTimer,InvasionTimer=140,CombatTimer,SlapAge=99;public V Slap,Pointer;public int? Watched,Grabbed;public string Notice="它们已经入住。选食物，给桌面加餐。";public double NoticeTime=4;
 private V? sweepAnchor;private readonly Random random;private int invaderSerial;
 public static string[] SnackNames={"饼干","蛋糕","奶酪","草莓","巨型披萨","整块蛋糕"};public static int[] Servings={24,64,42,32,900,1200};
 public World(double width,double height,int seed=0) {Width=width;Height=height;random=seed==0?new Random():new Random(seed);EnsureDay();Populate(false);}
 public double Rng(double a,double b)=>a+random.NextDouble()*(b-a);
 public V Safe(V p)=>new(Math.Clamp(p.X,25,Math.Max(26,Width-25)),Math.Clamp(p.Y,35,Math.Max(36,Height-35)));
 public V Nest(Species s)=>s==Species.Roach?new V(84,Height-92):new V(Width-84,Height-92);
 public int Count(Species s)=>Bugs.Count(x=>x.Species==s);public int Limit(Species s)=>s==Species.Roach?60:240;
 public int Reserved(Species s)=>Count(s)+Eggs.Where(x=>x.Species==s).Sum(x=>x.Brood);
 public double Scale(Bug b,bool animated=true) {var baseSize=(.38+.62*b.Growth)*(b.Adult?(b.Soldier?1.18:b.Breeder?1.1:1):1);var cap=Math.Min(Math.Sqrt(Math.Max(100,Width-50)*Math.Max(100,Height-70)*.25/(130*78)),Math.Min((Width-50)*.86/130,(Height-70)*.86/78));if(PetId(b.Species)=="ant")cap*=1.25;else if(Upright(b.Species))cap*=65d/36;return baseSize*Math.Pow(Math.Max(1,cap/baseSize),animated?b.ShownBulk:b.Bulk);}
 public bool AntAvatarEnabled {get=>Upright(Species.Ant);set=>RightPetId=value?"avatar":"ant";}
 public double Radius(Bug b)=>(Upright(b.Species)?16:PetId(b.Species)=="ant"?11:29)*Scale(b);
 public V SafeBug(V p,Bug b) {var k=Scale(b);if(Upright(b.Species)){double avatarX=Math.Min(Math.Max(0,(Width-50)/2),18*k),avatarY=Math.Min(Math.Max(0,(Height-70)/2),20*k);return new V(Math.Clamp(p.X,25+avatarX,Width-25-avatarX),Math.Clamp(p.Y,35+avatarY,Height-35-avatarY));}var kind=PetId(b.Species);var back=kind=="rat"?-76:kind=="roach"?-47:-22;var front=kind=="rat"?43:kind=="roach"?95:24;var half=kind=="rat"?17:kind=="roach"?39:14;var cs=Math.Cos(b.Angle);var sn=Math.Sin(b.Angle);var corners=new[]{new V(back,-half),new V(back,half),new V(front,-half),new V(front,half)}.Select(v=>new V((v.X*cs-v.Y*sn)*k,(v.X*sn+v.Y*cs)*k)).ToArray();double lx=25-corners.Min(v=>v.X),rx=Width-25-corners.Max(v=>v.X),ty=35-corners.Min(v=>v.Y),by=Height-35-corners.Max(v=>v.Y);return new V(lx<=rx?Math.Clamp(p.X,lx,rx):Width/2,ty<=by?Math.Clamp(p.Y,ty,by):Height/2);}
 public bool BodyHit(Bug b,V p,double padding=0) {var d=p-b.P;var k=Scale(b);if(Upright(b.Species))return Math.Pow(d.X/(16*k+padding),2)+Math.Pow(d.Y/(18*k+padding),2)<=1;return Math.Pow((d.X*Math.Cos(b.Angle)+d.Y*Math.Sin(b.Angle))/((PetId(b.Species)=="ant"?14:34)*k+padding),2)+Math.Pow((-d.X*Math.Sin(b.Angle)+d.Y*Math.Cos(b.Angle))/((PetId(b.Species)=="ant"?8:15)*k+padding),2)<=1;}
 public double SnackScale(Snack s)=>s>=Snack.Pizza?Math.Min(Width-50,Height-70)*.42/56:1;
 public double FoodRadius(Food f)=>f.Original<=5?5:(f.Snack==Snack.Pizza?23:20)*SnackScale(f.Snack);
 public void Say(string text) {Notice=PetText(text);NoticeTime=5;}
 public DayReport Today {get{EnsureDay();return Reports[^1];}}
 public void EnsureDay() {string day=DateTime.Now.ToString("yyyy-MM-dd",CultureInfo.InvariantCulture);if(Reports.Count==0||Reports[^1].Day!=day)Reports.Add(new DayReport{Day=day});if(Reports.Count>90)Reports.RemoveRange(0,Reports.Count-90);}
 public void Record(string text) {Today.Events.Add(DateTime.Now.ToString("HH:mm",CultureInfo.InvariantCulture)+"  "+PetText(text));if(Today.Events.Count>120)Today.Events.RemoveRange(0,Today.Events.Count-120);}
 public string RelationName=>Relation==Relation.Hostile?"交战":Relation==Relation.Truce?"停火":"建交通商";
 public void SetRelation(Relation value,string reason="桌面主人调停") {if(Relation==value)return;Relation=value;RelationAge=0;DeathsAtPeace=Deaths;Fights.Clear();foreach(var b in Bugs)b.Opponent=null;Record("双方"+RelationName+"："+reason);Say("双方"+RelationName+"。"+reason);}
 public void Populate(bool battle) {Bugs.Clear();Corpses.Clear();Eggs.Clear();Foods.Clear();Splats.Clear();Invaders.Clear();Fights.Clear();Sweeps.Clear();Archived=0;Serial=0;FoodSerial=0;RoachFood=120;AntFood=180;Hatched=0;Grown=0;Deaths=0;Relation=Relation.Hostile;RelationAge=0;DeathsAtPeace=0;AutoFoodTimer=0;InvasionTimer=140;RoachBirth=6;AntBirth=5;Watched=null;Grabbed=null;
  for(int i=0;i<(battle?52:40);i++) {var s=i<(battle?10:8)?Species.Roach:Species.Ant;var p=Safe(Nest(s)+new V(Rng(s==Species.Ant?-240:-55,30),Rng(-150,15)));var b=new Bug{Id=Serial++,Species=s,P=p,Wander=p,Angle=Rng(-Math.PI,Math.PI),Phase=Rng(0,6.28),Breeder=s==Species.Roach?i%2==0:i==(battle?10:8)||i==(battle?11:9),Growth=i%4==3?.35:1};b.Health=b.Toughness;Bugs.Add(b);}AddFood(new V(Width*.47,Height*.57),Snack.Cookie,18);}
 public void StartRound(){Populate(true);Battle=true;Result=false;Paused=false;Interactive=true;Remaining=150;RoachScore=AntScore=0;Say("两分半抢饭开始！");}
 public void Companion(){Battle=false;Result=false;Interactive=false;Paused=false;Grabbed=null;sweepAnchor=null;Say("安心工作，鼠标可以穿过虫群。");}
 public bool AddFood(V p,Snack? kind=null,int? portions=null) {if(Foods.Count>=18){Say("桌面够吃啦，等它们搬完一些。");return false;}var s=kind??(portions.HasValue?Snack.Cookie:SelectedSnack);var amount=Math.Max(1,portions??Servings[(int)s]);Foods.Add(new Food{Id=++FoodSerial,P=Safe(p),Snack=s,Portions=amount,Original=amount,Angle=Rng(-.4,.4)});return true;}
 public double GrowthCeiling(Bug b) {var peers=Bugs.Where(x=>x.Species==b.Species&&x.Id!=b.Id).ToList();if(b.Bulk<=.30&&peers.Count(x=>x.Bulk>.3)>=Math.Max(2,(peers.Count+1)/5))return .30;return peers.Any(x=>x.Bulk>=.78)?.70:1;}
 public void Bite(Bug b,Food f) {if(b.Flight!=null||f.Portions<=0||b.Cooldown>0)return;double old=b.Toughness;int oldMorph=b.Morph;bool giant=f.Snack>=Snack.Pizza&&f.Original>5;int amount=Math.Min(f.Portions,Math.Max(1,(int)((b.Species==Species.Roach?5:2)*Math.Pow(1+b.Bulk*7,1.35))));f.Portions-=amount;if(b.Bulk<.42)b.Cargo+=Math.Max(0,amount-1);double ceiling=Math.Max(b.Bulk,Math.Min(giant?1:.3,GrowthCeiling(b)));b.Bulk=Math.Min(ceiling,b.Bulk+(giant?.23:.075));bool young=!b.Adult;b.Growth=Math.Min(1,b.Growth+.18);b.Meals++;b.BitePulse=.55;b.Cooldown=b.Bulk>=.42?2.4:1.1;b.Health=Math.Min(b.Toughness,b.Health+Math.Max(0,b.Toughness-old));if(young&&b.Adult){Grown++;Today.Grown++;}if(b.Morph!=oldMorph){Record("进食蜕变：#"+b.Id+"长成"+b.MorphTitle);Say(b.MorphTitle+"！");}}
 public bool PlaceEgg(Species s,V p) {int brood=s==Species.Roach?3:1;if(Reserved(s)+brood>Limit(s)){Say("这一边住满了，等空出名额再放卵。");return false;}var egg=new Egg{Id=Serial++,Species=s,P=Safe(p),Brood=brood,HatchTime=s==Species.Roach?28:22};Eggs.Add(egg);Watched=egg.Id;Say(s==Species.Roach?"放下一枚卵鞘，会陆续孵出3只。":"放下一枚蚁卵，等待孵化。");return true;}
 public void Life(double dt) {foreach(var b in Bugs)b.LayTime=Math.Max(0,b.LayTime-dt);foreach(var e in Eggs.ToArray()){double old=e.LayAge??3;if(e.LayAge.HasValue)e.LayAge=Math.Min(3,old+dt);e.Age+=Math.Max(0,dt-Math.Max(0,2.8-old));if(e.Age<e.HatchTime)continue;var b=new Bug{Id=Serial++,Species=e.Species,P=HatchPoint(e),Growth=0,Generation=e.Generation,Angle=Rng(-Math.PI,Math.PI)};b.Wander=b.P;b.Breeder=b.Species==Species.Roach?b.Id%2==0:b.Id%19==0;b.Health=b.Toughness;Bugs.Add(b);Hatched++;if(b.Species==Species.Roach)Today.RoachBorn++;else Today.AntBorn++;if(Watched==e.Id)Watched=b.Id;e.Brood--;e.Age=e.HatchTime-1;if(e.Brood<=0)Eggs.Remove(e);}
  foreach(var b in Bugs.Where(b=>!b.Adult)){bool fed=(b.Species==Species.Roach?RoachFood:AntFood)>0;if(!fed)continue;bool was=b.Adult;b.Growth=Math.Min(1,b.Growth+dt/(b.Species==Species.Roach?65:50));if(!was&&b.Adult){Grown++;Today.Grown++;b.Health=b.Toughness;}}
  RoachBirth-=dt;AntBirth-=dt;foreach(var s in new[]{Species.Roach,Species.Ant}){double timer=s==Species.Roach?RoachBirth:AntBirth;int stored=s==Species.Roach?RoachFood:AntFood;if(timer>0||stored<(s==Species.Roach?12:4))continue;var parentList=Bugs.Where(x=>x.Species==s&&x.Adult&&x.Breeder&&x.Flight==null&&x.LayTime<=0).ToArray();int parents=parentList.Length;int wanted=Math.Min(s==Species.Roach?3:8,parents);int cost=s==Species.Roach?12:4;for(int n=0;n<wanted&&stored>=cost&&Reserved(s)+(s==Species.Roach?3:1)<=Limit(s);n++){var adult=parentList[n%parents];OrientForLaying(adult);Eggs.Add(EmittedEgg(adult,Serial++));adult.LayTime=2.8;stored-=cost;}if(s==Species.Roach){RoachFood=stored;RoachBirth=17;}else{AntFood=stored;AntBirth=12;}}
 }
 public void Spill(Bug b,bool crushed){if(PetId(b.Species)!="roach"||Splats.Any(x=>x.BugId==b.Id))return;double k=Scale(b);var ink=new Random(unchecked(b.Id*7919+(int)(Clock*1000)+71));double radius=Math.Min(180,Math.Max(5,16*k*(crushed?1.4:.8)));var s=new Splat{BugId=b.Id,P=b.P,Radius=radius,Angle=b.Angle,Crushed=crushed};for(int n=0;n<Math.Min(64,(int)(32+Math.Min(28,k*5)));n++){double a=ink.NextDouble()*Math.PI*2;double reach=radius*((n%4==0?2.4:.85)+ink.NextDouble()*(n%4==0?2.6:2.35));s.Drops.Add(new Drop{Offset=new V(Math.Cos(a)*reach,Math.Sin(a)*reach*.7),Radius=radius*(.045+ink.NextDouble()*.145),Flight=.4+ink.NextDouble()*.42});}Splats.Add(s);if(Splats.Count>96)Splats.RemoveRange(0,Splats.Count-96);}
 public void Kill(Bug b,bool crushed,bool chemical=false){if(!Bugs.Remove(b))return;if(b.Cargo>0)AddFood(b.P,portions:b.Cargo);b.Cargo=0;b.Flight=null;b.Opponent=null;Corpses.Add(b.Copy());Spill(b,crushed);if(Corpses.Count>160){Archived+=Corpses.Count-160;Corpses.RemoveRange(0,Corpses.Count-160);}if(Grabbed==b.Id)Grabbed=null;if(!crushed&&!chemical){Deaths++;if(b.Species==Species.Roach)Today.RoachLost++;else Today.AntLost++;}}
 public void Swat(V p){if(SlapAge<.38)return;Slap=p;SlapAge=0;Sound=true;var victims=Bugs.Where(b=>BodyHit(b,p,50)).ToArray();Today.Swatted+=victims.Length;foreach(var b in victims)Kill(b,true);Eggs.RemoveAll(e=>e.P.Distance(p)<66);foreach(var v in Invaders.Where(v=>!v.Dead&&v.P.Distance(p)<100)){v.Health=0;Record("拖鞋击倒外敌");}ScareRoaches(p);if(victims.Length>0)Record("拖鞋拍死"+victims.Length+"只，尸体和汁液留在桌面");Say(victims.Length>0?"拍中了，按4用扫把清理。":"没拍着，它们倒是吓了一跳。");}
 public void SweepAt(V p){var bodies=Corpses.Where(b=>BodyHit(b,p,65)).ToList();var ids=bodies.Select(b=>b.Id).ToHashSet();var stains=Splats.Where(s=>ids.Contains(s.BugId)||s.Hit(p,65)).ToList();var eggs=Eggs.Where(e=>e.P.Distance(p)<70).ToList();var outsiders=Invaders.Where(v=>v.Dead&&v.P.Distance(p)<120).ToList();Corpses.RemoveAll(b=>ids.Contains(b.Id));Splats.RemoveAll(s=>stains.Contains(s));Eggs.RemoveAll(e=>eggs.Contains(e));Invaders.RemoveAll(v=>outsiders.Contains(v));Sweeps.Add(new Sweep{P=p,Bodies=bodies,Stains=stains,Eggs=eggs,Outsiders=outsiders});if(Sweeps.Count>8)Sweeps.RemoveAt(0);sweepAnchor=p;Say("扫走尸体、汁液和卵。");}
 public void Press(V p){if(!Interactive)return;Pointer=p;if(Tool==Tool.Shelter){MarkShelter(p);return;}if(Tool==Tool.Observe){Watched=Bugs.Where(b=>BodyHit(b,p,10)).OrderByDescending(b=>b.P.Y).Select(b=>(int?)b.Id).FirstOrDefault()??Eggs.Where(e=>e.P.Distance(p)<30).Select(e=>(int?)e.Id).FirstOrDefault();return;}if(Tool==Tool.RoachEgg||Tool==Tool.AntEgg){PlaceEgg(Tool==Tool.RoachEgg?Species.Roach:Species.Ant,p);return;}if(Paused)return;switch(Tool){case Tool.Food:var b=Bugs.Where(x=>BodyHit(x,p,5)).OrderByDescending(x=>x.P.Y).FirstOrDefault();var at=b==null?p:b.P+new V(Math.Cos(b.Angle),Math.Sin(b.Angle))*(Radius(b)+20*SnackScale(SelectedSnack));if(AddFood(at)&&b!=null)Bite(b,Foods[^1]);break;case Tool.Spray:Spray(p);break;case Tool.Slipper:Swat(p);break;case Tool.Broom:SweepAt(p);break;case Tool.Grab:Grabbed=Bugs.Where(x=>BodyHit(x,p,10)).OrderByDescending(x=>x.P.Y).FirstOrDefault()?.Id;if(Grabbed.HasValue){var held=Bugs.First(x=>x.Id==Grabbed);held.Flight=null;held.FlightWait=12;}break;}}
 public void Drag(V p){Pointer=p;if(Tool==Tool.Spray)Spray(p);if(Grabbed.HasValue){var b=Bugs.FirstOrDefault(x=>x.Id==Grabbed);if(b!=null)b.P=SafeBug(p,b);}if(Tool==Tool.Broom&&!Paused&&sweepAnchor.HasValue&&sweepAnchor.Value.Distance(p)>24){var a=sweepAnchor.Value;int steps=(int)Math.Ceiling(a.Distance(p)/24);for(int n=1;n<=steps;n++)SweepAt(a+(p-a)*(n/(double)steps));}}
 public void Release(){Grabbed=null;sweepAnchor=null;}
 public void NextSubject(){var ids=Eggs.Select(x=>x.Id).Concat(Bugs.Select(x=>x.Id)).ToList();if(ids.Count==0){Watched=null;return;}int i=Watched.HasValue?ids.IndexOf(Watched.Value):-1;Watched=ids[(i+1)%ids.Count];}
 public V SubjectPoint()=>Watched.HasValue?(Bugs.FirstOrDefault(x=>x.Id==Watched)?.P??Eggs.FirstOrDefault(x=>x.Id==Watched)?.P??Corpses.FirstOrDefault(x=>x.Id==Watched)?.P??Pointer):Pointer;
 public string Observation {get{var b=Bugs.FirstOrDefault(x=>x.Id==Watched);if(b!=null)return $"第{b.Generation}代 · {PetMorphTitle(b)} · 吃{b.Meals}口";var e=Eggs.FirstOrDefault(x=>x.Id==Watched);if(e!=null)return $"约{Math.Max(0,e.HatchTime-e.Age):0}秒孵化 · 余{e.Brood}只";return "";}}
 public bool Summon(InvaderKind kind){if(Invaders.Any(v=>!v.Dead)){Say("外敌还在桌面上。");return false;}double strength=1+(Bugs.Count>0?Bugs.Max(b=>b.Bulk):0)*2.5;Invaders.Add(new Invader{Id=1000000+ ++invaderSerial,Kind=kind,P=new V(Width/2,100),Health=VisitorRules.Health(kind)*strength});if(Invaders.Count>8)Invaders.RemoveAt(0);InvasionTimer=180;Record(VisitorRules.Name(kind)+"闯入桌面");Say(VisitorRules.Introduction(kind));return true;}
 public void UpdateInvaders(double dt)=>StepVisitors(dt);
 public void Combat(double dt){if(Relation!=Relation.Hostile)return;var adults=Bugs.Where(b=>b.Adult&&b.Flight==null&&b.Id!=Grabbed).ToArray();var counts=new Dictionary<int,int>();foreach(var b in adults){var enemy=adults.Where(e=>e.Species!=b.Species).OrderBy(e=>e.P.Distance(b.P)).FirstOrDefault();if(enemy==null){b.Opponent=null;continue;}double range=b.P.Distance(enemy.P);bool crowded=adults.Count(x=>x.P.Distance(b.P)<Math.Max(100,Radius(b)+Radius(enemy)+55))>=7;bool food=Foods.Any(f=>f.P.Distance(b.P)<FoodRadius(f)+100);if(range<Radius(b)+Radius(enemy)+100&&(crowded||food||b.Opponent==enemy.Id)){b.Opponent=enemy.Id;counts[enemy.Id]=counts.GetValueOrDefault(enemy.Id)+1;}else b.Opponent=null;}
  var damage=new Dictionary<int,double>();foreach(var b in adults){if(!b.Opponent.HasValue||b.AttackCooldown>0)continue;var enemy=adults.FirstOrDefault(x=>x.Id==b.Opponent);if(enemy==null||b.P.Distance(enemy.P)>Radius(b)+Radius(enemy)+56)continue;var attack=b.Bulk>=.42?Attack.Ram:b.Species==Species.Ant&&b.Morph>=3?Attack.Pincer:counts.GetValueOrDefault(enemy.Id)>1?Attack.Swarm:Attack.Bite;double cadence=attack==Attack.Ram?1.8:attack==Attack.Pincer?1.2:.6;double strength=(b.Species==Species.Roach?1.5:.55)*(b.Soldier?1.8:1)*(1+b.Bulk*4)*cadence;damage[enemy.Id]=damage.GetValueOrDefault(enemy.Id)+strength;b.AttackCooldown=cadence;b.AttackPose=.4;b.Hit=.15;enemy.Hit=.3;var direction=(enemy.P-b.P).Unit;enemy.P=SafeBug(enemy.P+direction*(attack==Attack.Ram?22:5)/(1+enemy.Bulk*3),enemy);Fights.Add(new Fight{Attacker=b.Id,From=b.P+direction*Radius(b)*.7,To=enemy.P-direction*Radius(enemy)*.7,Style=attack,Size=1+b.Bulk*2.5});}
  foreach(var b in adults){b.Health-=damage.GetValueOrDefault(b.Id);if(b.Health<=0)Kill(b,false);}if(damage.Count>0&&Deaths>0&&Deaths%6==0)Say("双方争食，出现伤亡。");if(Fights.Count>64)Fights.RemoveRange(0,Fights.Count-64);}
 public void Diplomacy(double dt){RelationAge+=dt;TradeTimer+=dt;if(Relation==Relation.Hostile&&RelationAge>45&&Deaths-DeathsAtPeace>=6)SetRelation(Relation.Truce,"连番伤亡，暂时休整");else if(Relation==Relation.Truce&&RelationAge>40&&RoachFood>=12&&AntFood>=12)SetRelation(Relation.Trade,"口粮充足，恢复往来");else if(Relation!=Relation.Hostile&&RelationAge>100&&(RoachFood<3||AntFood<3))SetRelation(Relation.Hostile,"一方缺粮，停火破裂");if(Relation==Relation.Trade&&TradeTimer>15){TradeTimer=0;int gap=RoachFood-AntFood;if(Math.Abs(gap)>8){int gift=Math.Min(4,Math.Abs(gap)/2);RoachFood+=gap>0?-gift:gift;AntFood+=gap>0?gift:-gift;Today.Trades++;Record("双方通商，转移"+gift+"份口粮");}}}
 public void Update(double delta){if(Paused)return;double dt=Math.Clamp(delta,0,.08);SprayCooldown=Math.Max(0,SprayCooldown-dt);foreach(var cloud in Sprays)cloud.Age+=dt;Sprays.RemoveAll(c=>c.Age>1.2);foreach(var cloud in Sprays.Where(c=>c.Age<.75))PoisonBugs(cloud.P);Clock+=dt;NoticeTime-=dt;SlapAge+=dt;foreach(var s in Splats)s.Age=Math.Min(4,s.Age+dt);foreach(var s in Sweeps)s.Age+=dt;Sweeps.RemoveAll(s=>s.Age>=.65);foreach(var f in Fights)f.Age+=dt;Fights.RemoveAll(f=>f.Age>=.55);if(Result)return;EnsureDay();Diplomacy(dt);if(Battle){Remaining-=dt;if(Remaining<=0){Remaining=0;Result=true;Release();Say(RoachScore==AntScore?"势均力敌！":RoachScore>AntScore?"蟑螂帮，抢饭成功！":"蚂蚁军团，搬空全场！");return;}}
  AutoFoodTimer+=dt;if(AutoFoodTimer>(Battle?12:7)&&Foods.Count<10){AutoFoodTimer=0;AddFood(new V(Rng(Width*.2,Width*.72),Rng(Height*.28,Height*.78)),(Snack)(FoodSerial%4));}Life(dt*(Battle?1:LifeRate));UpdateInvaders(dt);foreach(var b in Bugs)b.AttackCooldown=Math.Max(0,b.AttackCooldown-dt);CombatTimer+=dt;if(CombatTimer>=.6){Combat(CombatTimer);CombatTimer=0;}
  var positions=Bugs.Select(b=>(Bug:b,Position:b.P,Radius:Radius(b))).ToArray();var cells=new Dictionary<(int,int),List<(Bug Bug,V Position,double Radius)>>();foreach(var p in positions){var key=((int)(p.Position.X/70),(int)(p.Position.Y/70));if(!cells.TryGetValue(key,out var list))cells[key]=list=new();list.Add(p);}var giants=positions.Where(x=>x.Radius>55).ToArray();
  foreach(var b in Bugs.ToArray()){if(b.Id==Grabbed)continue;if(b.LayTime>0){b.Phase+=dt*1.5;continue;}b.FlightWait=Math.Max(0,(b.FlightWait??(8+b.Id%13))-dt);if(b.Flight==null&&b.Cargo==0&&b.FlightWait<=0&&b.Hit<=0&&!b.Opponent.HasValue&&Bugs.Count(x=>x.Flight!=null)<2)BeginFlight(b);if(Fly(b,dt))continue;b.Cooldown=Math.Max(0,b.Cooldown-dt);b.Hit=Math.Max(0,b.Hit-dt);b.Web=Math.Max(0,b.Web-dt);b.BitePulse=Math.Max(0,b.BitePulse-dt);b.ShownBulk+=(b.Bulk-b.ShownBulk)*Math.Min(1,dt*8);var goal=b.Wander;bool hasGoal=false;double speed=b.Species==Species.Roach?58:48;
   if(b.Cargo>0){goal=Nest(b.Species);hasGoal=true;if(b.P.Distance(goal)<Math.Max(26,(b.Species==Species.Roach?89:18)*Scale(b)+18)){if(b.Species==Species.Roach){RoachFood+=b.Cargo;RoachScore+=b.Cargo;}else{AntFood+=b.Cargo;AntScore+=b.Cargo;}Today.Delivered+=b.Cargo;b.Cargo=0;b.Cooldown=.5;}}
   else {var f=Foods.Where(f=>f.Portions>0).OrderBy(f=>f.P.Distance(b.P)).FirstOrDefault();if(f!=null){double reach=FoodRadius(f)+Radius(b)*.75+4;var d=b.P-f.P;var direction=d.Length<.01?new V(Math.Cos(b.Id*2.4),Math.Sin(b.Id*2.4)):d.Unit;goal=SafeBug(f.P+direction*reach,b);hasGoal=true;if(b.P.Distance(f.P)<reach+12){Bite(b,f);speed=12;}}}
   if(Relation==Relation.Hostile&&b.Opponent.HasValue){var opponent=Bugs.FirstOrDefault(x=>x.Id==b.Opponent&&x.Flight==null);if(opponent!=null){var direction=(b.P-opponent.P).Unit;goal=SafeBug(opponent.P+direction*(Radius(b)+Radius(opponent)+8+(b.Bulk>=.42&&b.AttackCooldown>.6?32:0)),b);hasGoal=true;speed=b.Bulk>=.42&&b.AttackCooldown<=.6?120:45;}}
   if(!hasGoal){b.WanderTime-=dt;if(b.WanderTime<=0||b.P.Distance(b.Wander)<15){b.Wander=SafeBug(new V(Rng(25,Width-25),Rng(35,Height-35)),b);b.WanderTime=Rng(2,7);}goal=b.Wander;}
   var nursery=ShelterGoal(b);if(nursery.HasValue){goal=nursery.Value;hasGoal=true;}
   var desired=(goal-b.P).Unit;var avoid=V.Zero;int cx=(int)(b.P.X/70),cy=(int)(b.P.Y/70);var near=new List<(Bug Bug,V Position,double Radius)>();for(int x=-1;x<=1;x++)for(int y=-1;y<=1;y++)if(cells.TryGetValue((cx+x,cy+y),out var list))near.AddRange(list);near.AddRange(giants.Where(g=>!near.Any(n=>n.Bug.Id==g.Bug.Id)));foreach(var n in near){if(n.Bug.Id==b.Id||n.Bug.Flight!=null)continue;var d=b.P-n.Position;double reach=Math.Max(7,(Radius(b)+n.Radius)*.7);if(d.Length<reach&&d.Length>.1)avoid+=d.Unit*((reach-d.Length)/reach);}
   var motion=(desired+avoid*.85).Unit;if(motion.Length>.01){double target=Math.Atan2(motion.Y,motion.X),diff=Math.Atan2(Math.Sin(target-b.Angle),Math.Cos(target-b.Angle));b.Angle+=diff*Math.Min(1,dt*5);}speed*=(!Battle?.72:1)*(.65+b.Growth*.35)*(1-b.Bulk*.4)*(b.Web>0?.25:1);b.P=SafeBug(b.P+motion*(Math.Min(speed*dt,(goal-b.P).Length)),b);b.Phase+=dt*(speed>15?14:5);b.Walking=speed>15&&motion.Length>.01;b.AttackPose=Math.Max(0,b.AttackPose-dt);
  }Foods.RemoveAll(f=>f.Portions<=0);
 }
 public void Resize(double width,double height){double sx=width/Width,sy=height/Height,k=Math.Min(sx,sy);Width=width;Height=height;foreach(var b in Bugs){b.Flight=null;b.LayTime=0;b.P=SafeBug(new V(b.P.X*sx,b.P.Y*sy),b);b.Wander=b.P;}foreach(var b in Corpses)b.P=Safe(new V(b.P.X*sx,b.P.Y*sy));foreach(var e in Eggs){e.LayAge=3;e.LayStart=null;e.P=Safe(new V(e.P.X*sx,e.P.Y*sy));}foreach(var place in Shelters)place.P=Safe(new V(place.P.X*sx,place.P.Y*sy));foreach(var f in Foods)f.P=Safe(new V(f.P.X*sx,f.P.Y*sy));foreach(var v in Invaders)v.P=Safe(new V(v.P.X*sx,v.P.Y*sy));foreach(var s in Splats){s.P=Safe(new V(s.P.X*sx,s.P.Y*sy));s.Radius=Math.Min(240,s.Radius*k);foreach(var d in s.Drops){d.Offset*=k;d.Radius=Math.Min(80,d.Radius*k);}}Fights.Clear();Sweeps.Clear();}
 public string ReportText(){EnsureDay();string s=$"当前关系：{RelationName}\n{TeamName(Species.Roach)} {Count(Species.Roach)} · {TeamName(Species.Ant)} {Count(Species.Ant)} · 卵 {Eggs.Count} · 尸体 {Corpses.Count+Archived}\n仅记录应用实际运行期间的事件。\n";foreach(var day in Reports.AsEnumerable().Reverse())s+=$"\n━━ {day.Day} ━━\n孵化：左队{day.RoachBorn}／右队{day.AntBorn}；成年{day.Grown}\n战死：左队{day.RoachLost}／右队{day.AntLost}；拍死{day.Swatted}\n搬粮{day.Delivered}；通商{day.Trades}次\n"+string.Join("\n",day.Events)+"\n";return s;}
 private static readonly JsonSerializerOptions JsonOptions=new(){PropertyNameCaseInsensitive=true,IgnoreReadOnlyProperties=true};
 public string SaveJson()=>JsonSerializer.Serialize(new Snapshot{Width=Width,Height=Height,Shelters=Shelters,Bugs=Bugs,Corpses=Corpses,Eggs=Eggs,Foods=Foods,Splats=Splats,Invaders=Invaders,Reports=Reports,Serial=Serial,FoodSerial=FoodSerial,RoachFood=RoachFood,AntFood=AntFood,Deaths=Deaths,Hatched=Hatched,Grown=Grown,RoachBirth=RoachBirth,AntBirth=AntBirth,Clock=Clock,Relation=Relation,RelationAge=RelationAge,DeathsAtPeace=DeathsAtPeace,Archived=Archived},JsonOptions);
 public void Restore(string json){var s=JsonSerializer.Deserialize<Snapshot>(json,JsonOptions)??throw new InvalidDataException("Empty save");bool finite(double x)=>double.IsFinite(x);bool pos(V p)=>finite(p.X)&&finite(p.Y);if(s.Version!=1||!finite(s.Width)||!finite(s.Height)||s.Width<100||s.Height<100||s.Bugs.Count>300||s.Eggs.Count>300||s.Corpses.Count>160||s.Foods.Count>18||s.Splats.Count>96||s.Invaders.Count>8||s.Shelters.Count>6||!s.Shelters.All(p=>pos(p.P))||!s.Invaders.All(v=>Enum.IsDefined(v.Kind)&&pos(v.P)&&finite(v.Health))||s.Reports.Count>90||!s.Bugs.All(b=>pos(b.P)&&finite(b.Bulk)&&b.Bulk>=0&&b.Bulk<=1&&finite(b.Growth)&&b.Growth>=0&&b.Growth<=1&&finite(b.Health))||!s.Eggs.All(e=>pos(e.P)&&e.Brood>0&&e.Brood<=3&&finite(e.HatchTime)&&e.HatchTime>0)||!s.Foods.All(f=>pos(f.P)&&f.Portions>=0&&Enum.IsDefined(f.Snack))||!s.Splats.All(j=>pos(j.P)&&finite(j.Radius)&&j.Radius>0&&j.Radius<=240&&finite(j.Angle)&&finite(j.Age)&&j.Drops.Count<=64&&j.Drops.All(d=>pos(d.Offset)&&finite(d.Radius)&&d.Radius>0&&d.Radius<=80&&finite(d.Flight)&&d.Flight>0&&d.Flight<=2))||s.Bugs.Select(b=>b.Id).Concat(s.Eggs.Select(e=>e.Id)).Distinct().Count()!=s.Bugs.Count+s.Eggs.Count||s.Bugs.Select(b=>b.Id).Concat(s.Eggs.Select(e=>e.Id)).Any(id=>id<0||id>=s.Serial))throw new InvalidDataException("Unsupported or invalid save");double width=Width,height=Height;Width=s.Width;Height=s.Height;Bugs=s.Bugs;Corpses=s.Corpses;Eggs=s.Eggs;Foods=s.Foods;Splats=s.Splats;foreach(var j in Splats)j.Age=Math.Max(1,j.Age);Shelters=s.Shelters;Invaders=s.Invaders;Reports=s.Reports;Serial=s.Serial;FoodSerial=s.FoodSerial;RoachFood=s.RoachFood;AntFood=s.AntFood;Deaths=s.Deaths;Hatched=s.Hatched;Grown=s.Grown;RoachBirth=s.RoachBirth;AntBirth=s.AntBirth;Clock=s.Clock;Relation=s.Relation;RelationAge=s.RelationAge;DeathsAtPeace=s.DeathsAtPeace;Archived=s.Archived;Resize(width,height);EnsureDay();}
}
